import pytest
import torch

import flag_gems

from . import accuracy_utils as utils

RESIZE_DTYPES = utils.FLOAT_DTYPES

# (size, sparse_dim, dense_dim, new_size)
# The operator's metadata-only relayout path covers shape changes that keep the
# stored-entry element count unchanged; a dense-extent change is outside the
# qualified operator's tested/benchmarked contract.
RESIZE_CASES = [
    ((16, 32, 4), 2, 1, (16, 64, 4)),
    ((8, 6, 4), 3, 0, (8, 12, 4)),
]


def _make_sparse_coo(shape, sparse_dim, nnz, dtype, device, seed=0):
    g = torch.Generator(device="cpu").manual_seed(seed)
    idx = torch.stack(
        [torch.randint(0, s, (nnz,), generator=g) for s in shape[:sparse_dim]]
    ).to(device)
    values = torch.randn(
        (nnz,) + tuple(shape[sparse_dim:]), dtype=dtype, generator=g
    ).to(device)
    t = torch.sparse_coo_tensor(idx, values, shape, device=device, dtype=dtype)
    return t.coalesce()


@pytest.mark.sparse_resize_
@pytest.mark.parametrize("size,sparse_dim,dense_dim,new_size", RESIZE_CASES)
@pytest.mark.parametrize("dtype", RESIZE_DTYPES)
def test_sparse_resize_(size, sparse_dim, dense_dim, new_size, dtype):
    inp = _make_sparse_coo(size, sparse_dim, 64, dtype, flag_gems.device)
    ref = utils.to_reference(inp.clone())
    torch.ops.aten.sparse_resize_(ref, new_size, sparse_dim, dense_dim)
    res = flag_gems.sparse_resize_(inp, new_size, sparse_dim, dense_dim)
    assert res is inp
    assert inp.shape == ref.shape
    assert inp.sparse_dim() == ref.sparse_dim()
    assert inp.dense_dim() == ref.dense_dim()
    assert inp._nnz() == ref._nnz()
    utils.gems_assert_equal(inp.to_dense(), ref.to_dense())


